SELECT 
FROM messages
WHERE conversation_id = #{conversationId}
ORDER BY id DESC
LIMIT #{limit}

SELECT 
FROM messages
WHERE conversation_id = #{conversationId} AND id < #{beforeId}
ORDER BY id DESC
LIMIT #{limit}

SELECT 
FROM messages
WHERE conversation_id = #{conversationId} AND id > #{afterId}
ORDER BY id ASC
LIMIT #{limit}
